  1	<?php
  2	/**
  3	 * Main bootstrapper used to set up the specialized 
  4	 * Application Test suite environment.
  5	 * 
  6	 * @package TestDriver
  7	 * @author Sebastian Mordziol <s.mordziol@mistralys.eu>
  8	 * @see TestSuiteBootstrap
  9	 */
 10	
 11	declare(strict_types=1);
 12	
 13	use Application\Bootstrap\Screen\TestSuiteBootstrap;
 14	
 15	/**
 16	 * The application root folder (this file's location)
 17	 * @var string
 18	 */
 19	const APP_ROOT = __DIR__.'/application';
 20	
 21	if(!defined('TESTS_ROOT')) {
 22	    define('TESTS_ROOT', __DIR__);
 23	}
 24	
 25	/**
 26	 * The folder in which the Application libraries
 27	 * are installed. This is the default using a
 28	 * composer structure.
 29	 *
 30	 * @var string
 31	 */
 32	const APP_INSTALL_FOLDER = __DIR__.'/../src';
 33	
 34	const APP_VENDOR_PATH = __DIR__.'/../vendor';
 35	
 36	/**
 37	 * Specifies that this is the framework's own test suite.
 38	 * It is necessary to determine the location of the tests
 39	 * folder, which is different from where it is located in
 40	 * the applications.
 41	 */
 42	const APP_FRAMEWORK_TESTS = true;
 43	
 44	/**
 45	 * The bootstrapper class that configures the
 46	 * application environment.
 47	 * @see Application_Bootstrap
 48	 */
 49	require_once APP_INSTALL_FOLDER.'/classes/Application/Bootstrap/Bootstrap.php';
 50	
 51	// The initialization includes the local configuration files,
 52	// and defines all global application settings.
 53	
 54	try
 55	{
 56	    Application_Bootstrap::init();
 57	    Application_Bootstrap::bootClass(TestSuiteBootstrap::class);
 58	}
 59	catch(Throwable $e)
 60	{
 61	    testsuite_dumpException($e);
 62	    exit;
 63	}
 64	
 65	
 66	/**
 67	* Used to display an exception's details before the framework
 68	* error handling is loaded.
 69	*
 70	* @param Throwable $e
 71	*/
 72	function testsuite_dumpException(Throwable $e) : void
 73	{
 74	    $trace = $e->getTrace();
 75	
 76	    $root = str_replace('\\', '/', realpath(__DIR__.'/../'));
 77	
 78	    $cnt = 0;
 79	
 80	    echo PHP_EOL.
 81	    '--------------------------------------------------'.PHP_EOL.
 82	    'APP FRAMEWORK TESTSUITE EXCEPTION'.PHP_EOL.
 83	    '--------------------------------------------------'.PHP_EOL.
 84	    PHP_EOL.
 85	    'Message: '.$e->getMessage().PHP_EOL.
 86	    'Code: '.$e->getCode().PHP_EOL.
 87	    PHP_EOL;
 88	
 89	    foreach($trace as $entry)
 90	    {
 91	        $cnt++;
 92	
 93	        $class = '';
 94	        if(isset($entry['class'])) {
 95	            $class = $entry['class'].'::';
 96	        }
 97	
 98	        $file = str_replace('\\', '/', $entry['file']);
 99	        $file = str_replace($root, '', $file);
100	        $file = ltrim($file, '/');

